from topics_a import t, T
I='immigration'
t('immigration-advisor',I,'an immigration adviser',"Immigration advisers help people apply for visas, extend or switch status, settle and naturalise, and respond to refusals.",["Check IAA or legal regulation before paying.","Applications must meet detailed evidence rules.","Keep copies of everything submitted."])
t('immigration-consultant',I,'an immigration consultant',"Immigration consultants advise individuals and employers on UK visa routes, sponsor licences and compliance; they must be regulated to give advice.",["\"Consultant\" is not a protected title; check regulation.","Employers need sponsor compliance.","Get fees in writing."])
t('oisc-advisor',I,'an OISC-registered adviser',"OISC-registered advisers, now regulated by the Immigration Advice Authority, are authorised at specific levels to give immigration advice.",["The OISC became the IAA in 2025.","Check the adviser's level.","Registered advisers must display their status."])
t('visa-advisor',I,'a visa adviser',"Visa advisers help you choose the right route, prepare evidence and submit applications for work, family, study and visit visas.",["Choosing the right route is the first step.","Evidence rules are strict.","Check processing times."])
t('visa-consultant',I,'a visa consultant',"Visa consultants guide applicants through UK visa requirements, documents and timing; check they are regulated.",["Ask about experience with your route.","Avoid unregulated agents.","Plan around travel dates."])
t('visa-help',I,'help with a UK visa',"If you need help with a UK visa, a regulated adviser can check eligibility, prepare documents and reduce the risk of refusal.",["Refusals can affect future applications.","Use official Home Office guidance as a reference.","Keep your status valid."])
t('work-visa-advisor',I,'a work visa adviser',"Work visa advisers help skilled workers, global talent applicants and others meet salary, sponsorship and English requirements.",["Skilled worker visas need a licensed sponsor.","Salary thresholds apply.","Check the occupation code."])
t('spouse-visa-advisor',I,'a spouse visa adviser',"Spouse and partner visa advisers help couples meet the financial, relationship, accommodation and English requirements.",["The financial requirement is strict.","Evidence of relationship matters.","Plan for extension and settlement."])
t('student-visa-advisor',I,'a student visa adviser',"Student visa advisers help applicants with CAS, financial evidence and switching options after study.",["Funds must be held for the required period.","Check your sponsor's details.","Graduate routes have their own rules."])
t('visitor-visa-advisor',I,'a visitor visa adviser',"Visitor visa advisers help prepare applications showing the purpose of the visit, funds and intention to leave the UK.",["Explain the visit purpose clearly.","Show ties to your home country.","Some nationalities need an ETA instead."])
t('business-visa-advisor',I,'a business visa adviser',"Business visa advisers advise on business visits, sponsored work, global business mobility and founder routes.",["Business visitors cannot work in the UK.","Founder routes need endorsement.","Employers need sponsor licences."])
t('innovator-visa-advisor',I,'an Innovator Founder visa adviser',"Innovator Founder visa advisers help entrepreneurs secure endorsement for innovative, viable and scalable business ideas.",["Endorsement is required from an approved body.","Business plans must be strong.","Check-in meetings follow endorsement."])
t('british-citizenship-advisor',I,'a British citizenship adviser',"Citizenship advisers help people apply to naturalise or register as British citizens, including checking residence and good character requirements.",["Absences from the UK must be within limits.","Good character is assessed carefully.","Ceremony follows approval."])
t('asylum-advisor',I,'an asylum adviser',"Asylum advisers support people seeking protection in the UK through screening, interviews, evidence and appeals.",["Legal aid is often available for asylum.","Tell the truth consistently.","Keep all Home Office letters."])
t('asylum-solicitor',I,'an asylum solicitor',"Asylum solicitors represent people claiming protection, prepare statements and evidence, and handle appeals and fresh claims.",["Legal aid often covers asylum.","Interviews are key moments.","Appeals have short deadlines."])
t('appeal-immigration-advisor',I,'an immigration appeal adviser',"Immigration appeal advisers handle appeals to the First-tier Tribunal, administrative reviews and judicial reviews after refusals.",["Deadlines are very short.","Not every refusal has a right of appeal.","Fresh evidence may help."])
A='architect'
t('architect',A,'an architect',"An architect designs buildings and alterations, prepares drawings for planning and building regulations, and can oversee construction.",["Check the ARB register.","Agree scope by RIBA stage.","Discuss budget openly."])
t('chartered-architect',A,'a chartered architect',"Chartered architects are RIBA members, and RIBA Chartered Practices meet standards for insurance, quality and professional development.",["RIBA chartered status is in addition to ARB registration.","Ask for the RIBA practice directory listing.","Check relevant projects."])
t('house-architect',A,'a house architect',"Residential architects design new homes and transform existing houses, balancing space, light, budget and planning policy.",["Bring examples of homes you like.","Discuss lifestyle needs.","Plan budget contingency."])
t('home-extension-architect',A,'an architect for a home extension',"Extension architects design rear, side and wraparound extensions that work with your existing house and planning rules.",["Some extensions are permitted development.","Party wall matters may arise.","Consider light and flow."])
t('house-extension-architect',A,'a house extension architect',"House extension architects help you add space with single or double storey extensions, from concept to construction drawings.",["Check permitted development limits.","Neighbours may be consulted.","Structural engineers are usually needed."])
t('kitchen-extension-architect',A,'a kitchen extension architect',"Kitchen extension architects create open-plan kitchen, dining and living spaces, planning glazing, rooflights and services.",["Kitchen layout affects drainage and services.","Glazing affects energy rules.","Plan for living without a kitchen during works."])
t('loft-conversion-architect',A,'a loft conversion architect',"Loft conversion architects design dormers, hip-to-gable and mansard conversions, dealing with stairs, headroom and fire safety.",["Head height is key.","Fire escape rules apply.","Many lofts fall under permitted development."])
t('garage-conversion-architect',A,'a garage conversion architect',"Garage conversion architects turn garages into living space, considering insulation, windows, foundations and parking.",["Some conversions need planning permission.","Building regulations always apply.","Check covenants."])
t('basement-conversion-architect',A,'a basement conversion architect',"Basement architects design conversions and new basements, coordinating waterproofing, structure and neighbours.",["Waterproofing design is critical.","Party wall agreements are likely.","Some councils restrict basements."])
t('barn-conversion-architect',A,'a barn conversion architect',"Barn conversion architects work with agricultural buildings, balancing character, structure and planning rules.",["Class Q rights may apply in England.","Bats and ecology surveys are common.","Structural condition matters."])
t('listed-building-architect',A,'a listed building architect',"Listed building architects understand historic fabric and secure listed building consent for alterations.",["Unauthorised works to a listed building are a criminal offence.","Heritage statements are required.","Traditional materials matter."])
t('conservation-architect',A,'a conservation architect',"Conservation architects specialise in historic buildings, repairs and sensitive alterations, often with AABC accreditation.",["Look for AABC or RIBA conservation accreditation.","Repairs use compatible materials.","Grants may be available."])
t('conservation-area-architect',A,'an architect for conservation areas',"Architects experienced with conservation areas design changes that respect local character and meet stricter planning controls.",["Permitted development rights are reduced.","Article 4 directions may apply.","Materials and details matter."])
t('contemporary-house-architect',A,'a contemporary house architect',"Contemporary house architects design modern new homes and bold remodels with open plans, large glazing and high performance.",["Strong design statements help planning.","Energy performance is key.","Budget for quality materials."])
t('eco-home-architect',A,'an eco home architect',"Eco home architects design low-energy homes with insulation, airtightness, renewables and sustainable materials.",["Consider whole-life carbon.","Heat pumps need good insulation.","Grants may support upgrades."])
t('passivhaus-architect',A,'a Passivhaus architect',"Passivhaus architects design to the Passivhaus standard for very low energy use, comfort and air quality.",["Certified designers have specific training.","Airtightness testing is required.","Detailing is critical."])
t('commercial-architect',A,'a commercial architect',"Commercial architects design offices, retail, hospitality and industrial buildings, often within tight programmes.",["Business needs drive the brief.","Fire safety rules are strict.","Fit-out and shell work differ."])
t('office-architect',A,'an office architect',"Office architects design workplaces and fit-outs that support how teams work, including hybrid working.",["Lease terms may restrict alterations.","Consider acoustics and wellbeing.","Plan phasing to keep working."])
t('interior-architect',A,'an interior architect',"Interior architects redesign internal spaces, layouts and finishes, often working on refurbishments and fit-outs.",["Structural changes need engineers.","Building regulations still apply.","Lighting design transforms spaces."])
t('landscape-architect',A,'a landscape architect',"Landscape architects design gardens, public spaces and landscapes, and prepare landscape and visual assessments for planning.",["Look for Landscape Institute chartered members.","Planting plans take time to mature.","Drainage design matters."])
